def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = []
    opp = []
    for a, b in history:
        my.append(a)
        opp.append(b)

    total_c = 0
    for x in opp:
        if x == 'C':
            total_c += 1

    last_m = my[-1]
    last_o = opp[-1]

    w = min(n, 12)
    recent_c = 0
    for i in range(n - w, n):
        if opp[i] == 'C':
            recent_c += 1

    oD = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        oD += 1
        i -= 1

    start = max(1, n - 12)
    unprov_recent = 0
    for i in range(start, n):
        if opp[i] == 'D' and my[i - 1] == 'C':
            unprov_recent += 1

    coop_high = total_c * 100 > n * 72
    recent_high = recent_c * 100 > w * 55
    coop_mid = total_c * 100 > n * 50
    recent_low = recent_c * 100 < w * 35

    if last_o == 'D':
        if oD == 1:
            if total_c == 0:
                return 'C'
            if coop_high and recent_high and unprov_recent <= 1:
                return 'C'
            return 'D'

        if oD == 2:
            return 'D'

        if total_c == 0:
            max_f = 5 if n <= 20 else 2
        elif n <= 30 or coop_high:
            max_f = 5
        elif coop_mid:
            max_f = 4
        elif not recent_low:
            max_f = 3
        else:
            max_f = 2

        if oD <= max_f:
            return 'C'

        if total_c > 0 and rng.random() < 0.01:
            return 'C'

        return 'D'

    if n > 30 and recent_c * 100 < w * 25:
        return 'D'

    return 'C'
